query:
SELECT pg_catalog.jsonb_build_object(
'expected_versions', (SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('version',version,'name',name,'statement_count',pg_catalog.cardinality(statements),'statement_vector_sha256',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.array_to_json(statements)::text,'UTF8')),'hex')) ORDER BY version) FROM supabase_migrations.schema_migrations WHERE version=ANY(ARRAY['20261008192455','20261008200719','20261008201635','20261011072824','20261011085342','20261011094346','20261011100730','20261011103501','20261011105114','20261011110108','20261011175912','20261013093518','20261013190000','20261013190100','20261013190200','20261016090000','20261017043000','20261017140000','20261017160000']::text[])),
'base_without_evidence',(SELECT pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'root',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('version',version,'name',name,'statements',statements) ORDER BY version),'[]'::jsonb)::text,'UTF8')),'hex')) FROM supabase_migrations.schema_migrations WHERE version<>ALL(ARRAY['20261017043000','20261017140000','20261017160000']::text[]))
) AS metadata;
